        vm.editHistoryPage = 1;
        vm.editHistoryPagination = null;

        vm.toggleClubEditHistory = function() {
            vm.showEditHistory = !vm.showEditHistory;
            if (vm.showEditHistory && vm.clubEditHistory.length === 0) {
                vm.loadClubEditHistory(1);
            }
        };

        vm.loadClubEditHistory = function(page) {
            vm.editHistoryPage = page || 1;
            FlightEditsService.GetHistoryByClub(vm.club_id, vm.editHistoryPage, 20)
                .then(function(data) {
                    if (data && data.success) {
                        vm.clubEditHistory = data.edits || [];
                        vm.editHistoryPagination = data.pagination || null;
                    }
                });
        };


        // ═══════════════════════════════════════════════
        // FLIGHT MERGE — Duplicate Reconciliation
        // ═══════════════════════════════════════════════
        vm.mergeCandidateCount = 0;

        vm.loadMergeCandidateCount = function() {
            FlightMergeService.GetCandidatesByClub(vm.club_id).then(function(data) {
                if (data && data.success) {
                    vm.mergeCandidateCount = data.total_candidates || 0;
                }
            });
        };

        // Load merge candidate count on init
        vm.loadMergeCandidateCount();

        vm.openFlightMerge = function() {
            var modalInstance = $uibModal.open({
                animation: true,
                templateUrl: 'views/modals/flightMergeModal.html',
                controller: 'FlightMergeModalController',
                size: 'lg',
                backdrop: 'static',
                keyboard: false,
                resolve: {
                    clubId: function() { return vm.club_id; }
                }
            });

            modalInstance.result.then(function(result) {
                if (result && result.merged) {
                    ToastService.success('Merge Complete', 'Flight records have been merged successfully.', { duration: 4000 });
                    vm.search_for_flights();
                    vm.loadMergeCandidateCount();
                }
            }, function() {
                $log.info('Flight merge modal dismissed');
                // Refresh count in case user viewed but didn't merge
                vm.loadMergeCandidateCount();
            });
        };


        // ═══════════════════════════════════════════════
        // CANCEL CLAIM — Claimed flight cancellation
        // ═══════════════════════════════════════════════
        vm.is_manager = (vm.user.access && vm.user.access.manager &&
            vm.user.access.manager.indexOf(vm.club_id) > -1);

        vm.isFlightClaimed = function(flight) {
            // A flight is claimed if it has fox_claimed == 1 and a user assigned
            return flight && flight.fox_claimed == 1 && flight.user && flight.user.id;
        };

        vm.cancelClaim = function(flight) {
            var flightPlsId = flight.pls_id || flight.id;

            var modalInstance = $uibModal.open({
                animation: true,
                templateUrl: 'views/modals/cancelClaimModal.html',
                controller: 'CancelClaimModalController',
                size: 'lg',
                backdrop: 'static',
                keyboard: false,
                resolve: {
                    plsId: function() { return flightPlsId; },
                    clubId: function() { return vm.club_id; },
                    flightInfo: function() {
                        return {
                            registration: flight.aircraft ? flight.aircraft.registration : '',
                            date: flight.flight_date,
                            student: flight.user ? (flight.user.first_name + ' ' + flight.user.last_name) : ''
                        };
                    }
                }
            });

            modalInstance.result.then(function(result) {
                if (result && result.cancelled) {
                    ToastService.success('Claim Cancelled', 'The flight claim has been cancelled. The flight is now available for re-claiming.', { duration: 5000 });
                    vm.search_for_flights();
                }
            }, function() {
                $log.info('Cancel claim modal dismissed');
            });
        };


