        vm.convert_decimal_to_hours = function(decimal_time){
            var temp = new Array();
            temp = decimal_time.toString().split('.');
            
            var hours = temp[0];
            if(hours < 10){
                hours = "0"+hours;
            }
            if(temp[1]){
               var minutes = 100 / temp[1];
                minutes = Math.round(60 / minutes); 

                if(minutes < 10){
                    minutes = "0"+minutes;
                }
            } else {
                minutes = "00"
            }

            return hours + ':' + minutes;
        }








