// MaintenanceFleetController — fleet list + per-aircraft detail tabs.
// Routes:
//   dashboard.maintenance.fleet              → list
//   dashboard.maintenance.fleet.aircraft     → detail with tab=… query param
app.controller('MaintenanceFleetController', MaintenanceFleetController);

MaintenanceFleetController.$inject = ['$rootScope', '$scope', '$state', '$stateParams', 'ToastService', 'MaintenanceAccessService'];
function MaintenanceFleetController($rootScope, $scope, $state, $stateParams, ToastService, MaintenanceAccessService) {
    var vm = this;

    function parentCtx() {
        var p = $scope.$parent;
        while (p && !p.vm) p = p.$parent;
        return p && p.vm ? p.vm : {};
    }
    var ctx = parentCtx();
    vm.org_id    = ctx.org_id;
    vm.is_admin  = !!ctx.is_admin;
    vm.is_senior = !!ctx.is_senior;
    vm.can_edit  = vm.is_admin || vm.is_senior;

    vm.plane_id = $stateParams.plane_id ? parseInt($stateParams.plane_id, 10) : null;
    vm.action   = vm.plane_id ? 'detail' : 'list';

    vm.loading  = true;
    vm.fleet    = [];
    vm.search   = '';

    // detail state
    vm.plane          = null;
    vm.tab            = 'checks';
    vm.checks         = [];
    vm.flights        = [];
    vm.issues         = [];
    vm.airframe_log   = [];
    vm.engine_logs    = {};   // engine_id → []
    vm.prop_logs      = {};   // prop_id   → []
    vm.tab_loading    = false;
    vm.tab_counts     = { checks:0, flights:0, issues:0, airframe:0 };

    vm.setTab        = setTab;
    vm.formatDate    = formatDate;
    vm.checkStatus   = checkStatus;
    vm.issueStatus   = issueStatus;
    vm.openAddCheck  = openAddCheck;

    if (vm.action === 'list') {
        loadFleet();
    } else {
        loadDetail();
    }

    function loadFleet() {
        vm.loading = true;
        MaintenanceAccessService.Fleet(vm.org_id).then(function(res) {
            vm.loading = false;
            if (res && res.success !== false) {
                vm.fleet = (res.fleet || res.aircraft || res.data || res || []);
                if (!angular.isArray(vm.fleet)) vm.fleet = [];
            } else {
                ToastService.error('Failed to load fleet', res && res.message);
            }
        });
    }

    function loadDetail() {
        vm.loading = true;
        MaintenanceAccessService.Fleet(vm.org_id).then(function(res) {
            var fleet = (res && (res.fleet || res.aircraft || res.data || res)) || [];
            if (!angular.isArray(fleet)) fleet = [];
            vm.plane = find(fleet, function(p) { return parseInt(p.plane_id || p.id, 10) === vm.plane_id; });
            if (!vm.plane) {
                vm.loading = false;
                ToastService.error('Aircraft not found', 'This aircraft is not nominated to your organisation.');
                $state.go('dashboard.maintenance.fleet');
                return;
            }
            vm.loading = false;
            setTab('checks');
        });
    }

    function setTab(tab) {
        vm.tab = tab;
        vm.tab_loading = true;
        var pid = vm.plane_id;
        var p;

        if (tab === 'checks')   p = MaintenanceAccessService.Checks(pid).then(function(r){ vm.checks = list(r, 'checks'); vm.tab_counts.checks = vm.checks.length; });
        else if (tab === 'flights') p = MaintenanceAccessService.Flights(pid).then(function(r){ vm.flights = list(r, 'flights'); vm.tab_counts.flights = vm.flights.length; });
        else if (tab === 'issues')  p = MaintenanceAccessService.Issues(pid).then(function(r){ vm.issues = list(r, 'issues'); vm.tab_counts.issues = vm.issues.length; });
        else if (tab === 'airframe') p = MaintenanceAccessService.AirframeLogbook(pid).then(function(r){ vm.airframe_log = list(r, 'entries'); vm.tab_counts.airframe = vm.airframe_log.length; });
        else if (tab.indexOf('engine:') === 0) {
            var eid = parseInt(tab.split(':')[1], 10);
            p = MaintenanceAccessService.EngineLogbook(pid, eid).then(function(r){ vm.engine_logs[eid] = list(r, 'entries'); });
        }
        else if (tab.indexOf('prop:') === 0) {
            var prid = parseInt(tab.split(':')[1], 10);
            p = MaintenanceAccessService.PropellerLogbook(pid, prid).then(function(r){ vm.prop_logs[prid] = list(r, 'entries'); });
        }

        if (p && p.finally) p.finally(function() { vm.tab_loading = false; });
        else vm.tab_loading = false;
    }

    function openAddCheck() {
        // Delegate to the existing club maintenance check form.
        if (!vm.can_edit) return;
        $state.go('dashboard.manage_club.maintenance.detail', { plane_id: vm.plane_id });
    }

    function list(r, key) {
        if (!r) return [];
        var v = r[key] || r.data || r;
        return angular.isArray(v) ? v : [];
    }
    function find(arr, pred) {
        for (var i = 0; i < arr.length; i++) if (pred(arr[i])) return arr[i];
        return null;
    }
    function formatDate(s) {
        if (!s) return '—';
        s = String(s).substring(0, 10);
        return s;
    }
    function checkStatus(c) {
        if (!c.expiry_date) return { cls:'mxo-badge--slate', label:'No expiry' };
        var days = Math.floor((new Date(c.expiry_date).getTime() - Date.now()) / 86400000);
        if (days < 0)  return { cls:'mxo-badge--danger', label:'Overdue' };
        if (days < 14) return { cls:'mxo-badge--warn',   label:'Due soon' };
        return { cls:'mxo-badge--ok', label:'OK' };
    }
    function issueStatus(i) {
        var s = (i.status || '').toLowerCase();
        if (s === 'closed' || s === 'resolved') return { cls:'mxo-badge--ok', label:'Resolved' };
        if (s === 'in_progress' || s === 'open') return { cls:'mxo-badge--warn', label: i.status };
        return { cls:'mxo-badge--info', label: i.status || 'Reported' };
    }
}

// MaintenanceLicencesController — engineering licences across all org members.
// Numbers + documents are encrypted server-side; we only request the decrypted
// list when the user explicitly clicks "Reveal".
app.controller('MaintenanceLicencesController', MaintenanceLicencesController);

MaintenanceLicencesController.$inject = ['$rootScope', '$scope', '$window', 'ToastService',
    'EngineeringLicenceService', 'MaintenanceOrgMemberService'];
function MaintenanceLicencesController($rootScope, $scope, $window, ToastService,
    EngineeringLicenceService, MaintenanceOrgMemberService) {

    var vm = this;

    function parentCtx() {
        var p = $scope.$parent;
        while (p && !p.vm) p = p.$parent;
        return p && p.vm ? p.vm : {};
    }

    var ctx = parentCtx();
    vm.org_id    = ctx.org_id;
    vm.is_admin  = !!ctx.is_admin;
    vm.is_senior = !!ctx.is_senior;
    vm.can_edit  = vm.is_admin || vm.is_senior;

    vm.loading   = true;
    vm.members   = [];        // [{id, user_id, first_name, last_name, licences:[...]}]
    vm.search    = '';
    vm.show_form = false;
    vm.editing   = null;
    vm.form      = newForm();

    vm.openAdd     = openAdd;
    vm.openEdit    = openEdit;
    vm.closeForm   = closeForm;
    vm.saveLicence = saveLicence;
    vm.removeLicence = removeLicence;
    vm.reveal      = reveal;
    vm.downloadDoc = downloadDoc;
    vm.expiryClass = expiryClass;
    vm.expiryLabel = expiryLabel;

    // ── File upload (ng-flow) ──
    $scope.processLicenceFile = function(files) {
        if (!files || !files.length) return;
        try {
            var j = JSON.parse(files[files.length - 1].file_return);
            vm.form.document = {
                temp_path: j.saved_url,
                name: (j.files && j.files.file && j.files.file.name) || 'document'
            };
            $scope.$applyAsync();
        } catch(e) {
            ToastService.error('Upload error', 'Could not parse upload response.');
        }
    };

    load();

    function load() {
        if (!vm.org_id) { vm.loading = false; return; }
        vm.loading = true;
        MaintenanceOrgMemberService.ListByOrg(vm.org_id).then(function(res) {
            var members = (res && (res.members || res.data || res)) || [];
            if (!angular.isArray(members)) members = [];
            vm.members = members.map(function(m) { m.licences = []; m.expanded = false; return m; });

            // Fan-out: load licences per member.
            var done = 0;
            if (!vm.members.length) { vm.loading = false; return; }
            vm.members.forEach(function(m) {
                EngineeringLicenceService.ListByMember(m.id).then(function(r) {
                    var list = (r && (r.licences || r.data || r)) || [];
                    if (!angular.isArray(list)) list = [];
                    m.licences = list;
                    if (++done === vm.members.length) vm.loading = false;
                });
            });
        });
    }

    function newForm() {
        return {
            org_member_id: null,
            user_id: null,
            licence_type: '',
            licence_number: '',
            issued_date: '',
            expiry_date: '',
            document: null
        };
    }

    function openAdd(member) {
        if (!vm.can_edit) return;
        vm.editing = null;
        vm.form = newForm();
        vm.form.org_member_id = member.id;
        vm.form.user_id = member.user_id;
        vm.form._member_label = (member.first_name || '') + ' ' + (member.last_name || '');
        vm.show_form = true;
    }

    function openEdit(member, licence) {
        if (!vm.can_edit) return;
        // Need decrypted number for editing — fetch on demand.
        EngineeringLicenceService.ListDecrypted(member.id).then(function(r) {
            var list = (r && (r.licences || r.data || r)) || [];
            var dec = find(list, function(l) { return l.id === licence.id; }) || licence;
            vm.editing = licence;
            vm.form = {
                org_member_id:  member.id,
                user_id:        member.user_id,
                licence_type:   dec.licence_type   || '',
                licence_number: dec.licence_number || '',
                issued_date:    (dec.issued_date || '').substring(0, 10),
                expiry_date:    (dec.expiry_date || '').substring(0, 10),
                document:       null,
                _member_label:  (member.first_name || '') + ' ' + (member.last_name || ''),
                _has_document:  !!dec.has_document
            };
            vm.show_form = true;
        });
    }

    function closeForm() {
        vm.show_form = false;
        vm.editing = null;
        vm.form = newForm();
    }

    function saveLicence() {
        if (!vm.can_edit) return;
        var checks = [
            { ok: !!vm.form.licence_type,   field: 'mxl_type',  label: 'Licence type' },
            { ok: !!vm.form.licence_number, field: 'mxl_num',   label: 'Licence number' },
            { ok: !!vm.form.expiry_date,    field: 'mxl_exp',   label: 'Expiry date' }
        ];
        if (!ToastService.validateForm(checks)) return;

        var payload = {
            maintenance_org_id: vm.org_id,
            org_member_id:      vm.form.org_member_id,
            user_id:            vm.form.user_id,
            licence_type:       vm.form.licence_type,
            licence_number:     vm.form.licence_number,
            issued_date:        vm.form.issued_date || null,
            expiry_date:        vm.form.expiry_date
        };
        if (vm.form.document && vm.form.document.temp_path) {
            payload.document = { temp_path: vm.form.document.temp_path };
        }

        var op = vm.editing
            ? EngineeringLicenceService.Update(vm.editing.id, payload)
            : EngineeringLicenceService.Create(payload);

        op.then(function(res) {
            if (res && res.success !== false) {
                ToastService.success(vm.editing ? 'Licence updated' : 'Licence added',
                    'Expires ' + payload.expiry_date, { confetti: !vm.editing });
                closeForm(); load();
            } else {
                ToastService.error('Could not save', res && res.message);
            }
        });
    }

    function removeLicence(licence) {
        if (!vm.can_edit) return;
        if (!confirm('Delete this engineering licence? This cannot be undone.')) return;
        EngineeringLicenceService.Remove(licence.id).then(function(res) {
            if (res && res.success !== false) {
                ToastService.success('Licence deleted', null, { confetti: false });
                load();
            } else {
                ToastService.error('Could not delete', res && res.message);
            }
        });
    }

    function reveal(member, licence) {
        EngineeringLicenceService.ListDecrypted(member.id).then(function(r) {
            var list = (r && (r.licences || r.data || r)) || [];
            var dec = find(list, function(l) { return l.id === licence.id; });
            if (dec && dec.licence_number) {
                licence._revealed = dec.licence_number;
            } else {
                ToastService.error('Reveal failed', (r && r.message) || 'Could not decrypt.');
            }
        });
    }

    function downloadDoc(licence) {
        EngineeringLicenceService.GetFile(licence.id).then(function(r) {
            if (r && r.success && r.data) {
                var mime = mimeFor(r.type);
                var dataUri = 'data:' + mime + ';base64,' + r.data;
                // Open in a new tab; the browser handles PDFs/images natively.
                var w = $window.open();
                if (w) {
                    if (r.type === 'pdf') {
                        w.location.href = dataUri;
                    } else {
                        w.document.write('<img style="max-width:100%;height:auto" src="' + dataUri + '"/>');
                    }
                }
            } else {
                ToastService.error('Could not load document', r && r.message);
            }
        });
    }

    function expiryClass(licence) {
        if (!licence.expiry_date) return 'mxo-badge--slate';
        var days = daysUntil(licence.expiry_date);
        if (days < 0)  return 'mxo-badge--danger';
        if (days < 30) return 'mxo-badge--warn';
        return 'mxo-badge--ok';
    }
    function expiryLabel(licence) {
        if (!licence.expiry_date) return 'No expiry';
        var days = daysUntil(licence.expiry_date);
        if (days < 0)  return 'Expired ' + (-days) + 'd ago';
        if (days < 30) return 'Expires in ' + days + 'd';
        return licence.expiry_date.substring(0,10);
    }
    function daysUntil(iso) {
        var t = new Date(iso).getTime();
        return Math.floor((t - Date.now()) / 86400000);
    }
    function mimeFor(t) {
        t = (t || '').toLowerCase();
        if (t === 'pdf') return 'application/pdf';
        if (t === 'png') return 'image/png';
        if (t === 'jpg' || t === 'jpeg') return 'image/jpeg';
        if (t === 'gif') return 'image/gif';
        return 'application/octet-stream';
    }
    function find(arr, pred) {
        for (var i = 0; i < arr.length; i++) if (pred(arr[i])) return arr[i];
        return null;
    }
}

